UPDATE generos SET descripcion = 'Relata una historia en la cual aparecen ciertos personajes en un tiempo y espacio determinados. Las descripciones son un punto central en este género, así como los diálogos y monólogos.' WHERE genero = 'Narrativo';
UPDATE generos SET descripcion = 'Transmite sentimientos y emociones a través de la voz lírica, ya sea en verso o en prosa, así mismo presenta la realidad desde su propia perspectiva.' WHERE genero = 'Lírico';
UPDATE generos SET descripcion = 'También llamado teatral, se caracteriza por contener obras con situaciones y conflictos en las que se hace uso del diálogo, con el propósito de que sean representadas en un escenario frente al público.' WHERE genero = 'Dramático';
UPDATE generos SET descripcion = 'El género didáctico es de reciente aparición, en este se presenta un tema, se expresa una opinión o se divulgan enseñanzas e ideas con respecto a ese tema.' WHERE genero = 'Didáctico';